// A. Follow the links: FR → TC (tested?), UC/BR → FR (source?), FR → TC reversed (what does a test verify?).
const UNTESTED_FR = ["FR-4","FR-8"];
const ORPHAN_FR = ["FR-9"];   // a birthday greeting nobody asked for: gold plating
const TESTS_WITHOUT_REQUIREMENT = ["TC-10"];   // dark mode is not a requirement of release 1

// B. Both sides of the boundary, the boundary itself, and an appointment already started.
const CANCEL_TESTS = [
  { hoursBefore: 24, expected: 'free' },
  { hoursBefore: 2.1, expected: 'free' },
  { hoursBefore: 2, expected: 'free' },
  { hoursBefore: 1.9, expected: 'refused' },
  { hoursBefore: 0.5, expected: 'refused' },
  { hoursBefore: -0.25, expected: 'refused' },
];

// C. Impact = the changed items + everything downstream; effort = sum of HOURS_PER_ITEM by type.
const CR07_AFFECTED = ["BR-03","CODE-BOOK","DES-BOOK","FR-1","FR-2","TC-01","TC-02","UC-02"];
const CR07_EFFORT_HOURS = 20;
const CR07_DECISION = {
  decision: 'Defer',
  rationale: 'The impact is 20 hours but only 18 hours of capacity remain before release 1, and family booking does not serve a release 1 objective; reconsider it for release 2.',
};
const CR_LIFECYCLE = ['Submitted', 'Evaluated', 'Approved', 'Change Made', 'Verified', 'Closed'];

